import { createRng } from '../lib/rng.js'
import { TODAY } from '../lib/date.js'

/**
 * Inventory transactions.
 * Backend contract: id, medicineId, type, quantity, reference, createdAt
 * Types: PURCHASE | SALE | RETURN | ADJUSTMENT | EXPIRED | DAMAGED
 * quantity is always positive; direction is implied by type (see TX_DIRECTION).
 *
 * History is generated by walking *backwards* from each batch's current
 * quantity, so the ledger always reconciles with on-hand stock.
 */

export const TX_TYPES = ['PURCHASE', 'SALE', 'RETURN', 'ADJUSTMENT', 'EXPIRED', 'DAMAGED']

export const TX_DIRECTION = { PURCHASE: 1, RETURN: 1, SALE: -1, EXPIRED: -1, DAMAGED: -1, ADJUSTMENT: 1 }

export const TX_META = {
  PURCHASE: { label: 'Purchase', tone: 'brand' },
  SALE: { label: 'Sale', tone: 'blue' },
  RETURN: { label: 'Return', tone: 'neutral' },
  ADJUSTMENT: { label: 'Adjustment', tone: 'neutral' },
  EXPIRED: { label: 'Expired', tone: 'red' },
  DAMAGED: { label: 'Damaged', tone: 'amber' },
}

export const HISTORY_DAYS = 90
const DAY = 86_400_000

/** Signed change for a transaction (ADJUSTMENT stores sign in `delta`). */
export const txDelta = (t) => (t.type === 'ADJUSTMENT' ? t.delta ?? t.quantity : TX_DIRECTION[t.type] * t.quantity)

export function generateTransactions(medicines) {
  const rng = createRng(4242)
  const txs = []
  let seq = 10420

  medicines.forEach((m, idx) => {
    // ~6% of batches are dead stock (no sales for 60+ days).
    const dead = m.quantity > m.minimumStock && idx % 17 === 5
    const velocity = Math.max(0.2, (m.minimumStock / 12) * rng.float(0.5, 1.6)) // units / day
    let stock = m.quantity
    const cap = Math.max(m.minimumStock * 2.6, m.quantity + 5)

    for (let day = 0; day < HISTORY_DAYS; day++) {
      const ts = (h) => new Date(TODAY.getTime() - day * DAY + h * 3_600_000 + rng.int(0, 59) * 60_000).toISOString()
      // Sales (walking backwards: before the sale, stock was higher)
      const quiet = dead && day < 64
      if (!quiet && rng.chance(Math.min(0.9, velocity / 2.2))) {
        const q = Math.max(1, Math.round(velocity * rng.float(0.6, 2.2)))
        txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'SALE', quantity: q, reference: `INV-${rng.int(240000, 289999)}`, createdAt: ts(rng.int(9, 20)) })
        stock += q
      }
      if (rng.chance(0.012)) {
        const q = rng.int(1, 3)
        txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'RETURN', quantity: q, reference: `RTN-${rng.int(1000, 9999)}`, createdAt: ts(rng.int(10, 18)) })
        stock -= q
      }
      if (rng.chance(0.006) && stock > 4) {
        const q = rng.int(1, 2)
        txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'DAMAGED', quantity: q, reference: 'Damaged in storage', createdAt: ts(rng.int(10, 18)) })
        stock += q
      }
      if (rng.chance(0.005)) {
        const d = rng.chance(0.5) ? 1 : -1
        txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'ADJUSTMENT', quantity: 1, delta: d, reference: 'Cycle count correction', createdAt: ts(rng.int(18, 21)) })
        stock -= d
      }
      // Purchase: when going backwards stock climbs above cap, a delivery must have happened.
      if (stock > cap) {
        const q = Math.max(m.minimumStock, Math.round((stock - m.minimumStock * 0.6) / 10) * 10)
        const qq = Math.min(q, stock - 1)
        txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'PURCHASE', quantity: qq, reference: `PO-${rng.int(5200, 5899)}`, createdAt: ts(rng.int(8, 11)) })
        stock -= qq
      }
      if (stock < 0) stock = 0
    }
  })

  // Historic write-offs of expired stock (already removed from shelves).
  const expiredRefs = [
    ['Cough Syrup lot write-off', 9],
    ['Quarterly expiry audit', 14],
    ['Cold-chain excursion', 6],
  ]
  expiredRefs.forEach(([ref, q], i) => {
    const m = medicines[(i * 37 + 11) % medicines.length]
    txs.push({ id: `TX-${seq++}`, medicineId: m.id, type: 'EXPIRED', quantity: q, reference: ref, createdAt: new Date(TODAY.getTime() - (20 + i * 23) * DAY + 15 * 3_600_000).toISOString() })
  })

  return txs.sort((a, b) => b.createdAt.localeCompare(a.createdAt))
}

/**
 * Daily closing stock for the last `days` days for one medicine, derived from
 * its transactions. Returns [{ date: ISO, stock }], oldest first.
 */
export function stockHistory(medicine, transactions, days = HISTORY_DAYS) {
  const mine = transactions.filter((t) => t.medicineId === medicine.id)
  const byDay = new Map()
  mine.forEach((t) => {
    const d = Math.floor((TODAY.getTime() + DAY - new Date(t.createdAt).getTime()) / DAY)
    byDay.set(d, (byDay.get(d) || 0) + txDelta(t))
  })
  const out = []
  let stock = medicine.quantity
  for (let d = 0; d < days; d++) {
    out.push({ date: new Date(TODAY.getTime() - d * DAY).toISOString().slice(0, 10), stock: Math.max(0, stock) })
    stock -= byDay.get(d) || 0
  }
  return out.reverse()
}

/** Units sold in the last `days` days per medicine id. */
export function salesByMedicine(transactions, days = 30) {
  const since = TODAY.getTime() - days * DAY
  const map = {}
  transactions.forEach((t) => {
    if (t.type === 'SALE' && new Date(t.createdAt).getTime() >= since) map[t.medicineId] = (map[t.medicineId] || 0) + t.quantity
  })
  return map
}

/** Date of the most recent sale per medicine id. */
export function lastSaleByMedicine(transactions) {
  const map = {}
  transactions.forEach((t) => {
    if (t.type === 'SALE' && (!map[t.medicineId] || t.createdAt > map[t.medicineId])) map[t.medicineId] = t.createdAt
  })
  return map
}
